public static void printDiagonals(int[][] array) {
    int n = array.length;
    int m = array[0].length;

    // Print primary diagonal
    for (int i = 0; i < n; i++) {
        System.out.print(array[i][i] + " ");
    }
    System.out.println();

    // Print secondary diagonal
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i + j == n - 1) {
                System.out.print(array[i][j] + " ");
                break;
            }
        }
    }
    System.out.println();

    // Print all other diagonals
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (i + j < n && i - j >= 0) {
                System.out.print(array[i][j] + " ");
            }
        }
        System.out.println();
    }
}
```

